local SandCoolerMaker = {}
local PRODUCTS = {
    iron_sandcooler = { name = "Železni hladilec za livarski pesek", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni hladilec za livarski pesek za livarje." },
    bronze_sandcooler = { name = "Bronast hladilec za livarski pesek", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast hladilec za livarski pesek za livarje." },
    silver_sandcooler = { name = "Srebrn hladilec za livarski pesek", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn hladilec za livarski pesek za livarje." },
    gilded_sandcooler = { name = "Pozlačen hladilec za livarski pesek", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen hladilec za livarski pesek za livarje." },
    jewel_set_sandcooler = { name = "Draguljast hladilec za livarski pesek", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast hladilec za livarski pesek za livarje." },
    royal_sovereign_sandcooler = { name = "Kraljevski suveren hladilec za livarski pesek", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren hladilec za livarski pesek z biseri za krono." },
}
local BUILDINGS = {
    sandcooler_workshop = { name = "Sandcooler delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    sandcooler_house = { name = "Sandcooler hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_sandcooler_atelier = { name = "Mojstrski sandcooler atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_sandcooler_palace = { name = "Suverena sandcooler palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
SandCoolerMaker.ironStock=18; SandCoolerMaker.bronzeStock=14; SandCoolerMaker.woodStock=10; SandCoolerMaker.leatherStock=8; SandCoolerMaker.silverStock=8; SandCoolerMaker.goldStock=6; SandCoolerMaker.jewelStock=4; SandCoolerMaker.pearlStock=4
SandCoolerMaker.productStock = {}; SandCoolerMaker.buildings = {}; SandCoolerMaker.maker = nil; SandCoolerMaker.activeMaking = {}; SandCoolerMaker.totalProducts = 0; SandCoolerMaker.dayTimer = 0
function SandCoolerMaker.init() SandCoolerMaker.ironStock=18; SandCoolerMaker.bronzeStock=14; SandCoolerMaker.woodStock=10; SandCoolerMaker.leatherStock=8; SandCoolerMaker.silverStock=8; SandCoolerMaker.goldStock=6; SandCoolerMaker.jewelStock=4; SandCoolerMaker.pearlStock=4; SandCoolerMaker.productStock={}; SandCoolerMaker.buildings={}; SandCoolerMaker.maker=nil; SandCoolerMaker.activeMaking={}; SandCoolerMaker.totalProducts=0; SandCoolerMaker.dayTimer=0; print("[SandCoolerMaker] Royal Sand Cooler Maker System initialized (6 products, 4 buildings)") end
function SandCoolerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SandCoolerMaker.maker={name=n or ("Hladilnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Hladilnik najet: %s (spretnost: %d)",SandCoolerMaker.maker.name,s),"success") end; return true end
function SandCoolerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SandCoolerMaker.build(id) local ok,e=SandCoolerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SandCoolerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SandCoolerMaker.getQualityBonus() local b=0; for _,bd in ipairs(SandCoolerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SandCoolerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and SandCoolerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and SandCoolerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and SandCoolerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and SandCoolerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and SandCoolerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SandCoolerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SandCoolerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SandCoolerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SandCoolerMaker.buildings==0 then return false,"Potrebna hladilna delavnica" end; if not SandCoolerMaker.maker then return false,"Potreben hladilnik" end; return true end
function SandCoolerMaker.make(pt,qty) qty=qty or 1; local ok,e=SandCoolerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then SandCoolerMaker.ironStock=SandCoolerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then SandCoolerMaker.bronzeStock=SandCoolerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then SandCoolerMaker.woodStock=SandCoolerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then SandCoolerMaker.leatherStock=SandCoolerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then SandCoolerMaker.silverStock=SandCoolerMaker.silverStock-d.silverCost*qty end; if d.goldCost then SandCoolerMaker.goldStock=SandCoolerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SandCoolerMaker.jewelStock=SandCoolerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SandCoolerMaker.pearlStock=SandCoolerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SandCoolerMaker.maker then t=math.max(1,t-math.floor(SandCoolerMaker.maker.skill/13)) end; table.insert(SandCoolerMaker.activeMaking,{id="sandcooler_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SandCoolerMaker.completeMaking(m) local q=1.0+(SandCoolerMaker.getQualityBonus()/100); if SandCoolerMaker.maker then q=q+(SandCoolerMaker.maker.skill/140) end; q=math.min(2.5,q); SandCoolerMaker.productStock[m.productType]=(SandCoolerMaker.productStock[m.productType] or 0)+m.quantity; SandCoolerMaker.totalProducts=SandCoolerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SandCoolerMaker.maker then SandCoolerMaker.maker.itemsMade=SandCoolerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SandCoolerMaker.maker.skill=math.min(100,SandCoolerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Hladilec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sandcooler.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SandCoolerMaker.update(dt) if not _G.state then return end; SandCoolerMaker.dayTimer=SandCoolerMaker.dayTimer+dt; if SandCoolerMaker.dayTimer>=30 then SandCoolerMaker.dayTimer=0; for i=#SandCoolerMaker.activeMaking,1,-1 do local m=SandCoolerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SandCoolerMaker.completeMaking(m); table.remove(SandCoolerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SandCoolerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SandCoolerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SandCoolerMaker.getStats() return {ironStock=SandCoolerMaker.ironStock,bronzeStock=SandCoolerMaker.bronzeStock,woodStock=SandCoolerMaker.woodStock,leatherStock=SandCoolerMaker.leatherStock,silverStock=SandCoolerMaker.silverStock,goldStock=SandCoolerMaker.goldStock,jewelStock=SandCoolerMaker.jewelStock,pearlStock=SandCoolerMaker.pearlStock,productStock=SandCoolerMaker.productStock,numBuildings=#SandCoolerMaker.buildings,hasMaker=SandCoolerMaker.maker~=nil,makerName=SandCoolerMaker.maker and SandCoolerMaker.maker.name or "—",makerSkill=SandCoolerMaker.maker and SandCoolerMaker.maker.skill or 0,activeMaking=#SandCoolerMaker.activeMaking,totalProducts=SandCoolerMaker.totalProducts} end
return SandCoolerMaker
